from solution import get_Inv_Count


def test_issue_example_given():
    """Example get_Inv_Count([1,20,6,4,5],5) == 5."""
    assert get_Inv_Count([1, 20, 6, 4, 5], 5) == 5  # pairs (20,6),(20,4),(20,5),(6,4),(6,5) = 5


def test_issue_sorted_ascending():
    """Count inversions in an array is zero when sorted ascending."""
    assert get_Inv_Count([1, 2, 3, 4], 4) == 0  # 0 pairs with i<j and arr[i]>arr[j], so 0


def test_issue_sorted_descending():
    """Count inversions in an array is maximal when sorted descending."""
    assert get_Inv_Count([5, 4, 3, 2, 1], 5) == 10  # 5*4/2 = 10


def test_issue_empty_array():
    """Count inversions in an array handles empty input."""
    assert get_Inv_Count([], 0) == 0  # 0 pairs exist, so 0


def test_issue_single_element():
    """Count inversions in an array with one element is zero."""
    assert get_Inv_Count([42], 1) == 0  # 0 pairs exist, so 0


def test_issue_two_elements_inverted():
    """Count inversions in an array counts one pair just above sorted order."""
    assert get_Inv_Count([2, 1], 2) == 1  # pairs (2,1) = 1


def test_issue_all_equal():
    """Count inversions in an array does not count equal elements."""
    assert get_Inv_Count([2, 2, 2], 3) == 0  # 0 pairs with strict >, so 0


def test_issue_duplicates_mixed():
    """Count inversions in an array with duplicates counts only strict greater."""
    assert get_Inv_Count([3, 2, 2, 1], 4) == 5  # (3,2)+(3,2)+(3,1)+(2,1)+(2,1) = 5


def test_issue_negative_numbers():
    """Count inversions in an array works with negative values."""
    assert get_Inv_Count([-3, -1, -2], 3) == 1  # only (-1,-2) with -1>-2, so 1


def test_issue_larger_mixed():
    """Count inversions in an array counts all out-of-order pairs."""
    assert get_Inv_Count([2, 3, 8, 6, 1], 5) == 5  # (2,1)+(3,1)+(8,6)+(8,1)+(6,1) = 5


def test_contract_callable_with_arr_n():
    """Public interface solution.get_Inv_Count(arr, n) is callable."""
    assert callable(get_Inv_Count)


def test_contract_returns_count_type():
    """Count inversions in an array returns a count."""
    result = get_Inv_Count([1, 2, 3], 3)  # 0 pairs, so 0
    assert isinstance(result, int)
